// Стандарт С++20:

#include <iostream>
#include <array>                                                      // Подключение заголовочного файла для работы с фиксированным классом-контейнером array, который четко определяет границы массива;
#include <vector>                                                     // Подключение заголовочного файла для работы с классом-контейнером vector для применения динамических массивов;
#include <format>

int main()
{
    std::array<double, 4> a1{1.2, 2.4, 3.6, 4.8};                     // Безопасная инициализация объекта а1 класса-контейнера array из 4 элементов. Объект хранит все свои данные в памяти (в стеке), который знает размер и границы массива;
    std::vector<double> a2(4);                                      // Объявление объекта а2 с помощью класса-контейнера vector. Объект хранит адрес динамического массива в памяти (в куче). Класс хранит данные о начале, конца, а так же размер самого массива;
    a2[0] = 1.0 / 3.0;                                                // В 1 элемент объекта под индексом 0 класса-контейнера vector, записывается результат выражения;
    a2[1] = 1.0 / 5.0;                                                // Во 2 элемент объекта под индексом 1 класса-контейнера vector, записывается результат выражения;
    a2[2] = 1.0 / 7.0;                                                // В 3 элемент объекта под индексом 2 класса-контейнера vector, записывается результат выражения;
    a2[3] = 1.0 / 9.0;                                                // В 4 элемент объекта под индексом 3 класса-контейнера vector, записывается результат выражения;
    std::array<double, 4> a3 {3.14, 2.72, 1.62, 1.41};                // Безопасная инициализация объекта а3 класса-контейнера array из 4 элементов. Объект хранит все свои данные в памяти (в стеке), который знает размер и границы массива;
    std::array<double, 4> a4 = a3;                                    // Безопасная инициализация объекта класса-контейнера array из 4 элементов типа double. Объект хранит все свои данные в памяти (в стеке), который знает размер и границы массива.
                                                                      // Из-за применения объектов созданных с помощью класса-контейнера array, можно записать данные одного объекта другому. С массива данное действие запрещено;

    std::cout << std::format("a1[2]: {} по адресу: {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку со значением 3 элемента объекта (массива) и его адресом (хранящегося в стеке).
        a1[2], static_cast<const void*>(&a1[2]));                 // static_cast<const void*> - применяется явное приведение к универсальному типу, чтобы функция format() смогла вывести адрес в шестнадцатеричной форме через спецификатор {:p};
    std::cout << std::format("a2[2]: {} по адресу: {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку со значением 3 элемента динамического массива и его адресом (хранящегося в куче);
        a2[2], static_cast<const void*>(&a2[2]));                 // static_cast<const void*> - применяется явное приведение к универсальному типу, чтобы функция format() смогла вывести адрес в шестнадцатеричной форме через спецификатор {:p};
    std::cout << std::format("a3[2]: {} по адресу: {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку со значением 3 элемента объекта (массива) и его адресом (хранящегося в стеке).
        a3[2], static_cast<const void*>(&a3[2]));                 // static_cast<const void*> - применяется явное приведение к универсальному типу, чтобы функция format() смогла вывести адрес в шестнадцатеричной форме через спецификатор {:p};
    std::cout << std::format("a4[2]: {} по адресу: {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку со значением 3 элемента объекта (массива) и его адресом (хранящегося в стеке).
        a4[2], static_cast<const void*>(&a4[2]));                 // static_cast<const void*> - применяется явное приведение к универсальному типу, чтобы функция format() смогла вывести адрес в шестнадцатеричной форме через спецификатор {:p};

    a1[-2] = 20.2;                                                    // Намеренная введенная ошибка. Запись значения в чужую область в памяти (выход за границы массива). Данное действие, конечно нельзя использовать, программа аварийно остановиться, дальше этой строки вывода текста не будет;
    std::cout << std::format("a1[-2]: {} по адресу: {:p}\n",       // Объект cout с помощью оператора << выводит отформатированную строку со значением чужого элемента или незадействованной областью памяти и ее адресом (хранящегося в стеке).
        a1[-2], static_cast<const void*>(&a1[-2]));               // static_cast<const void*> - применяется явное приведение к универсальному типу, чтобы функция format() смогла вывести адрес в шестнадцатеричной форме через спецификатор {:p};
    std::cout << std::format("a3[2]: {} по адресу: {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку со значением 3 элемента объекта (массива) и его адресом (хранящегося в стеке).
        a3[2], static_cast<const void*>(&a3[2]));                 // static_cast<const void*> - применяется явное приведение к универсальному типу, чтобы функция format() смогла вывести адрес в шестнадцатеричной форме через спецификатор {:p};
    std::cout << std::format("a4[2]: {} по адресу: {:p}\n",        // Объект cout с помощью оператора << выводит отформатированную строку со значением 3 элемента объекта (массива) и его адресом (хранящегося в стеке).
        a4[2], static_cast<const void*>(&a4[2]));                 // static_cast<const void*> - применяется явное приведение к универсальному типу, чтобы функция format() смогла вывести адрес в шестнадцатеричной форме через спецификатор {:p};
}


